CREATE DATABASE IF NOT EXISTS jci_jdp CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci; USE jci_jdp;
CREATE TABLE offices(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(20) UNIQUE NOT NULL,name VARCHAR(150) NOT NULL,type ENUM('HO','RO','DPC') NOT NULL,region_id BIGINT UNSIGNED NULL,state_name VARCHAR(100),is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(region_id) REFERENCES offices(id)) ENGINE=InnoDB;
INSERT INTO offices(code,name,type,state_name) VALUES('HO-KOL','Head Office — Kolkata','HO','West Bengal');
INSERT INTO offices(code,name,type,region_id,state_name) VALUES('RO-01','Regional Office 01','RO',1,'State 1'),('RO-02','Regional Office 02','RO',1,'State 2'),('RO-03','Regional Office 03','RO',1,'State 3'),('RO-04','Regional Office 04','RO',1,'State 4'),('RO-05','Regional Office 05','RO',1,'State 5');
INSERT INTO offices(code,name,type,region_id,state_name) VALUES('DPC-01','DPC 01 — Region 01','DPC',2,'State 1'),('DPC-02','DPC 02 — Region 02','DPC',3,'State 2'),('DPC-03','DPC 03 — Region 03','DPC',4,'State 3'),('DPC-04','DPC 04 — Region 04','DPC',5,'State 4'),('DPC-05','DPC 05 — Region 05','DPC',6,'State 5');
CREATE TABLE roles(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(40) UNIQUE NOT NULL,name VARCHAR(100) NOT NULL); INSERT INTO roles(code,name) VALUES('ADMIN','System Administrator'),('HO_MANAGER','Head Office Manager'),('RO_MANAGER','Regional Office Manager'),('DPC_OFFICER','DPC Officer'),('APPROVER','Approver'),('AUDITOR','Auditor');
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,email VARCHAR(190) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role_id BIGINT UNSIGNED NOT NULL,office_id BIGINT UNSIGNED NOT NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE,last_login_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(role_id) REFERENCES roles(id),FOREIGN KEY(office_id) REFERENCES offices(id),INDEX(office_id,is_active));
CREATE TABLE vendors(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,vendor_code VARCHAR(30) UNIQUE NOT NULL,name VARCHAR(180) NOT NULL,gstin VARCHAR(15),email VARCHAR(190),phone VARCHAR(25),office_id BIGINT UNSIGNED NULL,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(office_id) REFERENCES offices(id));
CREATE TABLE inventory_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,item_code VARCHAR(40) NOT NULL,item_name VARCHAR(180) NOT NULL,office_id BIGINT UNSIGNED NOT NULL,quantity DECIMAL(14,3) NOT NULL DEFAULT 0,unit VARCHAR(20) NOT NULL DEFAULT 'units',reorder_level DECIMAL(14,3) NOT NULL DEFAULT 0,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(office_id) REFERENCES offices(id),INDEX(office_id,item_code));
CREATE TABLE requisitions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,office_id BIGINT UNSIGNED NOT NULL,created_by BIGINT UNSIGNED NOT NULL,title VARCHAR(180) NOT NULL,description TEXT,quantity DECIMAL(14,3) NOT NULL,estimated_amount DECIMAL(14,2) NOT NULL DEFAULT 0,status ENUM('pending','approved','rejected','draft') NOT NULL DEFAULT 'pending',approved_by BIGINT UNSIGNED NULL,approved_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(office_id) REFERENCES offices(id),FOREIGN KEY(created_by) REFERENCES users(id),FOREIGN KEY(approved_by) REFERENCES users(id),INDEX(office_id,status,created_at));
CREATE TABLE requisition_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,requisition_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,event VARCHAR(30) NOT NULL,comment VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(requisition_id) REFERENCES requisitions(id),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,office_id BIGINT UNSIGNED NULL,action VARCHAR(50) NOT NULL,entity_type VARCHAR(80) NOT NULL,entity_id BIGINT UNSIGNED NULL,details_json JSON,ip_address VARCHAR(45),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(office_id) REFERENCES offices(id) ON DELETE SET NULL,INDEX(created_at),INDEX(entity_type,entity_id));
